.version 8.0
.target sm_89
.address_size 64
.visible .entry matvec_kernel(
    .param .u64 A_ptr,
    .param .u64 B_ptr,
    .param .u64 C_ptr,
    .param .u32 M,
    .param .u32 K
)
{
    .reg .pred %p<10>;
    .reg .f32  %f<50>;
    .reg .b32  %r<40>;
    .reg .b64  %rd<60>;
    .shared .align 4 .f32 sdata[256];
    ld.param.u64 %rd1, [A_ptr];
    ld.param.u64 %rd2, [B_ptr];
    ld.param.u64 %rd3, [C_ptr];
    ld.param.u32 %r1,  [M];
    ld.param.u32 %r2,  [K];
    cvta.to.global.u64 %rd1, %rd1;
    cvta.to.global.u64 %rd2, %rd2;
    cvta.to.global.u64 %rd3, %rd3;
    mov.u32 %r3, %ctaid.x;   // initial row index (grid-stride loop)
    mov.u32 %r4, %tid.x;     // thread index
    mov.u32 %r5, %ntid.x;    // block dim
    mov.u32 %r22, %nctaid.x; // grid dim (stride for outer row loop)
    // vectorized index base and stride: idx = tid*16, stride = blockDim*16 (4x float4 per thread per iter for ILP)
    // relies on K being a multiple of 16 (true for the target shapes)
    mul.lo.u32 %r23, %r4, 16;
    mul.lo.u32 %r21, %r5, 16;
