    // bounds check on row (partial-grid safety) -- also serves as loop exit
    setp.ge.u32 %p1, %r3, %r1;
    @%p1 bra EXIT;
    // row * K (64-bit)
    mul.wide.u32 %rd4, %r3, %r2;
    // accumulators (four independent chains for ILP)
    mov.f32 %f1, 0f00000000;
    mov.f32 %f13, 0f00000000;
    mov.f32 %f40, 0f00000000;
    mov.f32 %f41, 0f00000000;
    mov.u32 %r6, %r23;
INNER_LOOP:
    setp.ge.u32 %p2, %r6, %r2;
    @%p2 bra INNER_LOOP_END;
    cvt.u64.u32 %rd5, %r6;
    add.u64 %rd6, %rd4, %rd5;      // row*K + idx
    shl.b64 %rd7, %rd6, 2;
    add.u64 %rd8, %rd1, %rd7;
    ld.global.v4.f32 {%f2, %f3, %f4, %f5}, [%rd8];   // A[row,idx..idx+3]
    shl.b64 %rd10, %rd5, 2;
    add.u64 %rd11, %rd2, %rd10;
    ld.global.nc.v4.f32 {%f6, %f7, %f8, %f9}, [%rd11];  // B[idx..idx+3]
    add.u32 %r7, %r6, 4;
    cvt.u64.u32 %rd22, %r7;
    add.u64 %rd23, %rd4, %rd22;    // row*K + idx+4
    shl.b64 %rd24, %rd23, 2;
    add.u64 %rd25, %rd1, %rd24;
    ld.global.v4.f32 {%f14, %f15, %f16, %f17}, [%rd25];  // A[row,idx+4..idx+7]
