    cvt.u64.u32 %rd30, %r10;
    add.u64 %rd31, %rd4, %rd30;    // row*K + idx+8
    shl.b64 %rd32, %rd31, 2;
    add.u64 %rd33, %rd1, %rd32;
    ld.global.v4.f32 {%f22, %f23, %f24, %f25}, [%rd33];  // A[row,idx+8..idx+11]
    shl.b64 %rd34, %rd30, 2;
    add.u64 %rd35, %rd2, %rd34;
    ld.global.nc.v4.f32 {%f26, %f27, %f28, %f29}, [%rd35];  // B[idx+8..idx+11]
    add.u32 %r11, %r6, 12;
    cvt.u64.u32 %rd36, %r11;
    add.u64 %rd37, %rd4, %rd36;    // row*K + idx+12
    shl.b64 %rd38, %rd37, 2;
    add.u64 %rd39, %rd1, %rd38;
    ld.global.v4.f32 {%f32, %f33, %f34, %f35}, [%rd39];  // A[row,idx+12..idx+15]
    shl.b64 %rd40, %rd36, 2;
    add.u64 %rd41, %rd2, %rd40;
    ld.global.nc.v4.f32 {%f36, %f37, %f38, %f39}, [%rd41];  // B[idx+12..idx+15]
