    fma.rn.f32 %f13, %f14, %f18, %f13;
    fma.rn.f32 %f40, %f22, %f26, %f40;
    fma.rn.f32 %f41, %f32, %f36, %f41;
    fma.rn.f32 %f1, %f3, %f7, %f1;
    fma.rn.f32 %f13, %f15, %f19, %f13;
    fma.rn.f32 %f40, %f23, %f27, %f40;
    fma.rn.f32 %f41, %f33, %f37, %f41;
    fma.rn.f32 %f1, %f4, %f8, %f1;
    fma.rn.f32 %f13, %f16, %f20, %f13;
    fma.rn.f32 %f40, %f24, %f28, %f40;
    fma.rn.f32 %f41, %f34, %f38, %f41;
    fma.rn.f32 %f1, %f5, %f9, %f1;
    fma.rn.f32 %f13, %f17, %f21, %f13;
    fma.rn.f32 %f40, %f25, %f29, %f40;
    fma.rn.f32 %f41, %f35, %f39, %f41;
    add.u32 %r6, %r6, %r21;
