    add.f32 %f40, %f40, %f41;
    add.f32 %f1, %f1, %f40;
    mul.wide.u32 %rd12, %r4, 4;
    mov.u64 %rd13, sdata;
    add.u64 %rd14, %rd13, %rd12;
    st.shared.f32 [%rd14], %f1;
    bar.sync 0;
    mov.u32 %r8, 128;
