    setp.eq.u32 %p3, %r8, 0;
    @%p3 bra RED_DONE;
    setp.ge.u32 %p4, %r4, %r8;
    @%p4 bra RED_SKIP;
    mul.wide.u32 %rd15, %r4, 4;
    add.u64 %rd16, %rd13, %rd15;
    ld.shared.f32 %f10, [%rd16];
    add.u32 %r9, %r4, %r8;
    mul.wide.u32 %rd17, %r9, 4;
    add.u64 %rd18, %rd13, %rd17;
    ld.shared.f32 %f11, [%rd18];
    add.f32 %f12, %f10, %f11;
    st.shared.f32 [%rd16], %f12;
RED_SKIP:
    bar.sync 0;
    shr.u32 %r8, %r8, 1;
    bra RED_LOOP;
RED_DONE:
    setp.ne.u32 %p5, %r4, 0;
    @%p5 bra SKIP_WRITE;
    ld.shared.f32 %f13, [%rd13];
    cvt.u64.u32 %rd19, %r3;
    shl.b64 %rd20, %rd19, 2;
    add.u64 %rd21, %rd3, %rd20;
    st.global.f32 [%rd21], %f13;
