_ptx_module = None


def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module


def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("matvec_kernel")


class ModelNew(nn.Module):
    """
    Simple model that performs matrix-vector multiplication (C = A * B)
    using a custom PTX kernel.
    """

    def __init__(self):
        super().__init__()

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        assert A.is_cuda and B.is_cuda, "Inputs must be CUDA tensors"
        assert A.dtype == torch.float32 and B.dtype == torch.float32

        A = A.contiguous()
        B = B.contiguous()

        M, K = A.shape[0], A.shape[1]

        C = torch.empty((M, 1), dtype=A.dtype, device=A.device)

        module = _get_ptx_module()

        block_x = 256
        # Choose a grid size that evenly divides M so every CTA performs the
        # same number of grid-stride row iterations. The previous fixed cap
        # (min(M, 768)) could leave some CTAs with one extra row iteration
        # versus others, causing load imbalance and reduced achieved
        # occupancy (observed ~83% vs 100% theoretical). Finding the largest
        # divisor of M that is <= 768 removes this imbalance without
        # changing kernel semantics (grid-stride loop still handles any M).
        grid_x = min(M, 768)
        while grid_x > 1 and M % grid_x != 0:
            grid_x -= 1

        module.launch(
            "matvec_kernel",
            grid=(grid_x, 1, 1),
            block=(block_x, 1, 1),
            arguments=[A, B, C, i32(M), i32(K)],
            shared_memory=0,
            stream=torch.cuda.current_stream(A.device),
        )

        return C

